class Solution:
    def sequenceReconstruction(self, nums: List[int], sequences: List[List[int]]) -> bool:
        n = len(nums)
        adj = [[] for _ in range(n + 1)]
        indeg = [0] * (n + 1)
        seen = set()
        for seq in sequences:
            for a, b in zip(seq, seq[1:]):
                if (a, b) not in seen:
                    seen.add((a, b))
                    adj[a].append(b)
                    indeg[b] += 1
        q = deque(i for i in range(1, n + 1) if indeg[i] == 0)
        count = 0
        while q:
            if len(q) != 1:
                return False
            u = q.popleft()
            count += 1
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        return count == n

