var sequenceReconstruction = function(nums, sequences) {
    const n = nums.length;
    const adj = Array.from({length: n + 1}, () => []);
    const indeg = new Array(n + 1).fill(0);
    const seen = new Set();
    for (const seq of sequences)
        for (let j = 0; j + 1 < seq.length; j++) {
            const a = seq[j], b = seq[j + 1];
            const key = a * 100001 + b;
            if (!seen.has(key)) {
                seen.add(key);
                adj[a].push(b);
                indeg[b]++;
            }
        }
    let q = [];
    for (let i = 1; i <= n; i++)
        if (indeg[i] === 0) q.push(i);
    let count = 0;
    while (q.length) {
        if (q.length !== 1) return false;
        const next = [];
        const u = q.pop();
        count++;
        for (const v of adj[u])
            if (--indeg[v] === 0) next.push(v);
        q = next;
    }
    return count === n;
};

